{
  "pasos": [
    {
      "id": "s1",
      "op": "search_catalog",
      "args": {
        "query": "celular batería larga duración",
        "category": "celulares",
        "attributes": {"bateria_mah": {"min": 5000}},
        "limit": 3
      }
    },
    {
      "id": "s2",
      "op": "get_reviews",
      "args": {"product_id": "$s1.0.id", "limit": 3}
    },
    {
      "id": "s3",
      "op": "get_reviews",
